import ts from "typescript";

function once(source, from, to) {
  if (source.split(from).length !== 2) throw new Error(`Orchestration patch mismatch: ${from.slice(0, 70)}`);
  return source.replace(from, to);
}

// Keep the pinned panel's layout and readouts while removing administrative capabilities.
export function orchestrationPatches(source) {
  const tree = ts.createSourceFile("native.js", source, ts.ScriptTarget.Latest, true, ts.ScriptKind.JS);
  const edits = [];
  function visit(node) {
    if (ts.isFunctionDeclaration(node) && ["OrchestrationPanel", "ProfileDescriptionRow"].includes(node.name?.text)) {
      edits.push([node.getStart(tree), node.end, adapt(node.getText(tree), node.name.text)]);
      return;
    }
    ts.forEachChild(node, visit);
  }
  visit(tree);
  if (edits.length !== 2) throw new Error("Native orchestration component boundary changed");
  for (const [start, end, text] of edits.sort((a, b) => b[0] - a[0])) source = source.slice(0, start) + text + source.slice(end);
  return source;
}

function adapt(source, name) {
  const tree = ts.createSourceFile("panel.js", source, ts.ScriptTarget.Latest, true, ts.ScriptKind.JS);
  const edits = [];
  function visit(node) {
    if (ts.isVariableStatement(node)) {
      const names = node.declarationList.declarations.map(declaration => declaration.name.getText(tree));
      const remove = name === "OrchestrationPanel"
        ? ["saveSettings", "saveProfileDescription", "autoGenerateDescription", "profileOptions", "[busy, setBusy]"]
        : ["[draft, setDraft]", "busy", "tag"];
      if (names.some(value => remove.includes(value))) { edits.push([node.getStart(tree), node.end, ""]); return; }
    }
    if (ts.isCallExpression(node) && node.expression.getText(tree) === "h") {
      const kind = node.arguments[0]?.getText(tree);
      const props = node.arguments[1]?.getText(tree) ?? "";
      let replacement;
      if (name === "OrchestrationPanel" && kind === "Select") {
        const field = props.includes("settings.orchestrator_profile") ? "orchestrator_profile" : "default_assignee";
        replacement = `h("div", { className: "h-8 flex items-center text-xs" }, settings.${field} || "(default: " + settings.active_profile + ")")`;
      }
      if (name === "OrchestrationPanel" && kind === '"label"' && node.getText(tree).includes("h(Checkbox")) {
        replacement = 'h("div", { className: "flex items-center gap-2 text-xs h-8" }, settings.auto_decompose ? "Auto" : "Manual")';
      }
      if (name === "ProfileDescriptionRow" && kind === '"div"' && node.getText(tree).includes("h(Input")) {
        // Only replace the immediate edit row, preserving the profile metadata wrapper.
        if (props.includes('"flex items-center gap-2"')) replacement = 'h("div", { className: "text-xs", style: { whiteSpace: "pre-wrap", overflowWrap: "anywhere" } }, p.description || "No description.")';
      }
      if (replacement) { edits.push([node.getStart(tree), node.end, replacement]); return; }
    }
    ts.forEachChild(node, visit);
  }
  visit(tree);
  const expected = name === "OrchestrationPanel" ? 8 : 4;
  if (edits.length !== expected) throw new Error(`Native ${name} control inventory changed`);
  for (const [start, end, text] of edits.sort((a, b) => b[0] - a[0])) source = source.slice(0, start) + text + source.slice(end);
  if (name === "ProfileDescriptionRow") {
    return once(source, '    useEffect(function () {\n      setDraft(p.description || "");\n    }, [p.description]);', "");
  }
  source = once(source, '    const [msg, setMsg] = useState(null);', '    const [msg, setMsg] = useState(null);\n    const requestGeneration = useRef(0);');
  source = once(source, '    const loadAll = useCallback(function () {', `    const loadAll = useCallback(function () {
      const generation = ++requestGeneration.current;
      setSettings(null); setProfiles([]); setMsg(null);`);
  source = once(source, '        setSettings(results[0] || null);\n        setProfiles((results[1] && results[1].profiles) || []);', `        if (generation !== requestGeneration.current) return;
        const config = results[0], roster = results[1];
        const fields = ["orchestrator_profile", "default_assignee", "active_profile", "resolved_orchestrator_profile", "resolved_default_assignee"];
        if (!config || typeof config.auto_decompose !== "boolean" || fields.some(key => typeof config[key] !== "string") ||
            !roster || !Array.isArray(roster.profiles) || roster.profiles.some(p => !p || typeof p.name !== "string" || typeof p.description !== "string" || typeof p.is_default !== "boolean" || typeof p.description_auto !== "boolean")) {
          throw new TypeError("Invalid orchestration response");
        }
        setSettings(config);
        setProfiles(roster.profiles);`);
  source = once(source, '      }).catch(function (err) {', '      }).catch(function (err) {\n        if (generation !== requestGeneration.current) return;');
  source = once(source, '      if (settings === null) loadAll();\n    }, [settings, loadAll]);', '      loadAll();\n      return function () { requestGeneration.current++; };\n    }, [loadAll]);');
  const titleStart = source.indexOf("    const modePillTitle ="), titleEnd = source.indexOf('      title: modePillTitle,', titleStart);
  if (titleStart < 0 || titleEnd < 0) throw new Error("Native mode pill boundary changed");
  source = source.slice(0, titleStart) + `    const modePillTitle = "Read-only native orchestration configuration";
    const modePill = h("span", {
` + source.slice(titleEnd);
  source = once(source, 'settings === null ? "…" : (autoOn ? "Auto" : "Manual")', 'settings === null ? (msg ? "Unavailable" : "Loading…") : (autoOn ? "Auto" : "Manual")');
  source = once(source, 'Configure the kanban orchestrator (profile picker, default assignee, auto-decompose, profile descriptions)', 'Read-only native orchestration settings and profile descriptions');
  source = once(source, '        msg ? h("div", {', '        h("div", { className: "text-xs text-muted-foreground" }, "Read-only — configuration changes are unavailable here."),\n        msg ? h("div", {');
  source = once(source, '          "Loading…"),', '          msg ? "Unavailable" : "Loading…"),');
  source = once(source, 'Descriptions guide the decomposer\'s routing. Click ⚗ to auto-generate, or edit and save.', 'Native profile descriptions (read-only).');
  source = once(source, 'Triage tasks stay in triage until you click ⚗ Decompose.', 'Triage tasks await explicit decomposition in Hermes.');
  source = once(source, '          profiles.length === 0', '          settings === null ? h("div", { className: "text-xs text-muted-foreground" }, msg ? "Unavailable" : "Loading…") : profiles.length === 0');
  source = once(source, '                    busy: busy[p.name] || null,\n                    onSave: saveProfileDescription,\n                    onAuto: autoGenerateDescription,', "");
  return source;
}
